ah, Bitcoin Core does this:

friend inline bool operator&lt;(const base_blob&amp; a, const base_blob&amp; b) { return a.Compare(b) &lt; 0; }

inline int Compare(const base_blob&amp; other) const { return memcmp(data, other.data, sizeof(data)); }

